          "| Chuẩn bị giống | Phải là giống lúa cấp nguyên chủng hoặc xác nhận. Ưu tiên sử dụng giống lúa có năng suất cao, chất lượng tốt, kháng sâu, bệnh. | Chỉ gieo trồng giống tốt và trồng cây con khoẻ, không mang nguồn sâu, bệnh. Hạt giống cần xử lí hoá chất để tiêu diệt nguồn sâu, bệnh trước khi gieo. | Sử dụng các giống có năng suất cao, chất lượng tốt và phù hợp với điều kiện sinh thái. Một số giống cam thường được dùng như cam Vinh, cam Vân Du, cam Cao Phong,… Cây giống khoẻ mạnh, không bị sâu, bệnh, thân cành mập, bộ rễ phát triển khoẻ. |",
